import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

/**
 * iOS only uses a launch image whose media query matches the device exactly;
 * when none does it stretches whatever it has, which is how a landscape iPad
 * ends up with a squashed splash. The links are generated by
 * `bun run generate-assets` and pasted into index.html, so this guards the
 * paste: every declared device size must point at an image of the pixel size
 * that device actually has.
 */

interface SplashLink {
  deviceWidth: number;
  deviceHeight: number;
  ratio: number;
  landscape: boolean;
  href: string;
}

const ROOT = resolve(__dirname, '../..');

function splashLinks(): SplashLink[] {
  const html = readFileSync(resolve(ROOT, 'index.html'), 'utf8');
  return [...html.matchAll(/<link rel="apple-touch-startup-image" media="([^"]+)" href="([^"]+)" \/>/g)].map((match) => {
    const media = match[1];
    const orientation = /\(orientation: (\w+)\)/.exec(media)?.[1];
    return {
      deviceWidth: Number(/\(device-width: (\d+)px\)/.exec(media)?.[1]),
      deviceHeight: Number(/\(device-height: (\d+)px\)/.exec(media)?.[1]),
      ratio: Number(/\(-webkit-device-pixel-ratio: (\d+)\)/.exec(media)?.[1]),
      landscape: orientation === 'landscape',
      href: match[2],
    };
  });
}

/** Width and height straight out of the PNG's IHDR chunk. */
function pngSize(path: string): { width: number; height: number } {
  const buffer = readFileSync(resolve(ROOT, 'public', path.replace(/^\//, '')));
  expect(buffer.subarray(1, 4).toString('ascii')).toBe('PNG');
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

describe('iOS launch images', () => {
  const links = splashLinks();

  it('declares both orientations for every tablet and phone size', () => {
    const sizes = new Map<string, Set<boolean>>();
    for (const link of links) {
      const key = `${link.deviceWidth}x${link.deviceHeight}@${link.ratio}`;
      const orientations = sizes.get(key) ?? new Set<boolean>();
      orientations.add(link.landscape);
      sizes.set(key, orientations);
    }
    for (const [key, orientations] of sizes) {
      expect([...(orientations ?? [])].sort(), key).toEqual([false, true]);
    }
  });

  it('points every size at an image of exactly that pixel size', () => {
    for (const link of links) {
      const size = pngSize(link.href);
      const expected = link.landscape
        ? { width: link.deviceHeight * link.ratio, height: link.deviceWidth * link.ratio }
        : { width: link.deviceWidth * link.ratio, height: link.deviceHeight * link.ratio };
      expect(size, `${link.href} for ${link.deviceWidth}x${link.deviceHeight}`).toEqual(expected);
    }
  });

  it('covers the current iPads, whose splash is otherwise stretched in landscape', () => {
    const declared = links.map((link) => `${link.deviceWidth}x${link.deviceHeight}`);
    // iPad Pro 13"/Air 13" (M4) and iPad Pro 11" (M4).
    expect(declared).toContain('1032x1376');
    expect(declared).toContain('834x1210');
  });
});
